Widget buildOrders(List<Order> orders) => ListView.builder(
      itemCount: orders.length,
      // Lets a keyed item find its old element at a new index
      findChildIndexCallback: (key) {
        final i = orders.indexWhere((o) => ValueKey(o.id) == key);
        return i < 0 ? null : i;
      },
      itemBuilder: (context, i) => ExpansionTile(
        key: ValueKey(orders[i].id),
        title: Text('Order ${orders[i].id}'),
        children: [Text(orders[i].summary)],
      ),
    );
